/**
 * SlicyWeb
 * Recommendation End-To-End Tests
 *
 * Recommendation of the objects in the built application (Phase 10 lot 88;
 * ADR-035 D3, D11, D12 option B): generated by itself once the analysis is
 * up to date and a printer and a material are selected; Recommendation
 * section (object type, preset, warnings, confidence; the rest under
 * "Details", folded); object type chosen by the user and "Automatic";
 * Print Preset section and status bar; Tools > Generate Recommendations
 * and the Generate button; several selected objects.
 *
 * Based on:
 * - TEST_PLAN.md (End-To-End Testing; lot 88)
 * - GUI_SPEC.md (Recommendation Section, Print Preset Section, Tools Menu,
 *   Toolbar Buttons, Status Bar)
 */

import type { Page } from "@playwright/test";

import en from "../../public/locales/en.json";

import { cubeStl, expect, importFiles, test } from "./fixtures";

/** Section of the Properties Panel with this title */
function section(window: Page, title: string) {
  return window
    .locator("section")
    .filter({ has: window.getByRole("heading", { name: title }) })
    .last();
}

function recommendationSection(window: Page) {
  return section(window, en["recommendation.title"]);
}

/** Row "label value" of the Recommendation section */
function row(window: Page, label: string) {
  return recommendationSection(window)
    .locator("dl > div")
    .filter({ has: window.locator("dt", { hasText: label }) })
    .locator("dd");
}

test("generates the recommendation by itself and shows it", async ({
  window,
  files,
  started,
}) => {
  const objectType = window.getByLabel(en["recommendation.objectType"]);
  const generate = window
    .getByRole("toolbar", { name: en["toolbar.title"] })
    .getByRole("button", { name: en["toolbar.generate"] });

  await importFiles(window, [files("cube.stl", cubeStl("cube", 20))]);

  // Analysis done, no printer and no material: no recommendation yet
  await expect(objectType).toHaveValue("");
  await expect(objectType.locator("option").first()).toHaveText(
    en["recommendation.automatic"].replace(
      "{category}",
      en["classification.unknown"],
    ),
  );
  await expect(row(window, en["recommendation.status"])).toHaveText(
    en["recommendation.none"],
  );
  await expect(recommendationSection(window)).toContainText(
    en["recommendation.selectPrinterMaterial"],
  );
  await expect(generate).toHaveAttribute("aria-disabled", "true");

  await window.getByLabel(en["printer.selector"]).selectOption("prusa_mk4s");
  await window.getByLabel(en["material.selector"]).selectOption("pla");

  // A cube: unknown, Balanced preset; no filament -15, unknown -20
  await expect(row(window, en["recommendation.status"])).toHaveText(
    en["result.generated"],
  );
  await expect(
    row(window, en["recommendation.classificationConfidence"]),
  ).toHaveText(en["confidence.unknown"]);
  await expect(row(window, en["recommendation.preset"])).toHaveText(
    en["preset.balanced"],
  );
  await expect(row(window, en["recommendation.confidence"])).toHaveText(
    `65/100 (${en["recommendation.level.moderate"]})`,
  );
  await expect(
    recommendationSection(window).getByRole("list", {
      name: en["recommendation.warnings"],
    }),
  ).toContainText(en["warning.CLASSIFICATION_UNCERTAIN"]);
  await expect(recommendationSection(window)).not.toContainText(
    en["recommendation.selectPrinterMaterial"],
  );

  // Print Preset section and status bar
  await expect(section(window, en["preset.title"])).toContainText(
    en["preset.balanced"],
  );
  await expect(window.getByRole("contentinfo")).toContainText(
    `${en["statusBar.preset"]}:${en["preset.balanced"]}`,
  );

  // Details: folded by default
  const layerHeight = row(window, en["recommendation.layerHeight"]);
  await expect(layerHeight).toBeHidden();
  await recommendationSection(window)
    .getByText(en["recommendation.details"], { exact: true })
    .click();
  await expect(layerHeight).toHaveText("0.2 mm");
  await expect(row(window, en["recommendation.supports"])).toHaveText(
    en["recommendation.supportsNo"],
  );
  await expect(row(window, en["recommendation.adhesion"])).toHaveText(
    en["recommendation.adhesionType.skirt"],
  );

  // Object type chosen by the user: Prototype, Fast Prototype preset
  await objectType.selectOption("prototype");
  await expect(row(window, en["recommendation.preset"])).toHaveText(
    en["preset.fastPrototype"],
  );
  await expect(row(window, en["recommendation.confidence"])).toHaveText(
    `85/100 (${en["recommendation.level.high"]})`,
  );
  await expect(window.getByRole("contentinfo")).toContainText(
    `${en["statusBar.preset"]}:${en["preset.fastPrototype"]}`,
  );

  // Automatic again
  await objectType.selectOption("");
  await expect(row(window, en["recommendation.preset"])).toHaveText(
    en["preset.balanced"],
  );

  expect(started.errors).toEqual([]);
});

test("Tools > Generate Recommendations, Generate button and several objects", async ({
  window,
  files,
}) => {
  const tools = window.getByRole("menuitem", { name: en["menu.tools"] });
  const item = window.getByRole("menuitem", {
    name: en["tools.generateRecommendations"],
  });
  const generate = window
    .getByRole("toolbar", { name: en["toolbar.title"] })
    .getByRole("button", { name: en["toolbar.generate"] });

  // No object: disabled
  await tools.click();
  await expect(item).toHaveAttribute("aria-disabled", "true");
  await window.keyboard.press("Escape");

  await window.getByLabel(en["printer.selector"]).selectOption("prusa_mk4s");
  await window.getByLabel(en["material.selector"]).selectOption("pla");
  await expect(generate).toHaveAttribute("aria-disabled", "true");

  await importFiles(window, [
    files("a.stl", cubeStl("a", 10)),
    files("b.stl", cubeStl("b", 20)),
  ]);
  await expect(row(window, en["recommendation.status"])).toHaveText(
    en["result.generated"],
  );
  await expect(generate).not.toHaveAttribute("aria-disabled", "true");

  await generate.click();
  await expect(row(window, en["recommendation.status"])).toHaveText(
    en["result.generated"],
  );

  await tools.click();
  await expect(item).not.toHaveAttribute("aria-disabled", "true");
  await item.click();
  await expect(row(window, en["recommendation.status"])).toHaveText(
    en["result.generated"],
  );

  // Two objects selected
  await window
    .getByRole("heading", { name: en["recommendation.title"] })
    .click();
  await window.keyboard.press("ControlOrMeta+a");
  await expect(recommendationSection(window)).toContainText(
    en["analysis.selectSingle"],
  );
  await expect(section(window, en["preset.title"])).toContainText("—");
  await expect(window.getByRole("contentinfo")).toContainText(
    `${en["statusBar.preset"]}:—`,
  );
});
